import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function Anomalies() {
    const navigate = useNavigate();
    const [anomalies, setAnomalies] = useState([]);
    const [experts, setExperts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [selectedExpert, setSelectedExpert] = useState({});
    const [user, setUser] = useState(null);

    useEffect(() => {
        const userData = localStorage.getItem('user');
        if (userData) {
            setUser(JSON.parse(userData));
        }
        fetchAnomalies();
        fetchExperts();
    }, []);

    const fetchAnomalies = () => {
        fetch('http://localhost:8000/api/anomalies/')
            .then(res => res.json())
            .then(data => {
                setAnomalies(data);
                setLoading(false);
            })
            .catch(err => {
                console.error('Error:', err);
                setLoading(false);
            });
    };

    const fetchExperts = () => {
        fetch('http://localhost:8000/api/experts/')
            .then(res => res.json())
            .then(data => setExperts(data))
            .catch(err => console.error('Error:', err));
    };

    const handleAction = async (id, action, extraData = null) => {
        try {
            let url = `http://localhost:8000/api/anomalies/${id}/${action}/`;
            let options = {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
            };

            if (extraData) {
                options.body = JSON.stringify(extraData);
            }

            const response = await fetch(url, options);
            const data = await response.json();
            
            if (response.ok) {
                alert(data.message);
                fetchAnomalies();
            } else {
                alert(data.message || '❌ خطا در انجام عملیات!');
            }
        } catch (error) {
            alert('❌ خطا در اتصال به سرور!');
            console.error('Error:', error);
        }
    };

    const getStatusLabel = (status) => {
        const labels = {
            'new': 'جدید',
            'approved': 'تأیید شده',
            'assigned': 'تخصیص داده شده',
            'resolved': 'رفع شده',
            'closed': 'بسته شده'
        };
        return labels[status] || status;
    };

    const getStatusColor = (status) => {
        const colors = {
            'new': '#e3f2fd',
            'approved': '#fff3e0',
            'assigned': '#fce4ec',
            'resolved': '#e8f5e9',
            'closed': '#c8e6c9'
        };
        return colors[status] || '#f5f5f5';
    };

    const getStatusTextColor = (status) => {
        const colors = {
            'new': '#0d47a1',
            'approved': '#e65100',
            'assigned': '#c62828',
            'resolved': '#2e7d32',
            'closed': '#1b5e20'
        };
        return colors[status] || '#333';
    };

    const canApprove = user?.role === 'safety_supervisor';
    const canAssign = user?.role === 'safety_supervisor';
    const canResolve = user?.role === 'safety_expert' || user?.role === 'health_expert' || user?.role === 'environment_expert';
    const canClose = user?.role === 'safety_supervisor';

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                <h1>📋 لیست آنومالی‌ها</h1>
                <button
                    onClick={() => navigate('/anomalies/new')}
                    style={{
                        padding: '10px 20px',
                        backgroundColor: '#1976d2',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                    }}
                >
                    + ثبت آنومالی جدید
                </button>
            </div>

            {loading ? (
                <p>⏳ در حال بارگذاری...</p>
            ) : (
                <div style={{ overflowX: 'auto' }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', backgroundColor: 'white', borderRadius: '8px' }}>
                        <thead>
                            <tr style={{ backgroundColor: '#f5f5f5' }}>
                                <th style={{ padding: '12px', textAlign: 'right' }}>عنوان</th>
                                <th style={{ padding: '12px', textAlign: 'right' }}>مکان</th>
                                <th style={{ padding: '12px', textAlign: 'right' }}>سطح ریسک</th>
                                <th style={{ padding: '12px', textAlign: 'right' }}>وضعیت</th>
                                <th style={{ padding: '12px', textAlign: 'right' }}>ثبت‌کننده</th>
                                <th style={{ padding: '12px', textAlign: 'center' }}>عملیات</th>
                            </tr>
                        </thead>
                        <tbody>
                            {anomalies.length === 0 ? (
                                <tr>
                                    <td colSpan="6" style={{ textAlign: 'center', padding: '20px', color: '#666' }}>
                                        هیچ آنومالی ثبت نشده است
                                    </td>
                                </tr>
                            ) : (
                                anomalies.map((anomaly) => (
                                    <tr key={anomaly.id} style={{ borderBottom: '1px solid #eee' }}>
                                        <td style={{ padding: '12px' }}>{anomaly.title}</td>
                                        <td style={{ padding: '12px' }}>{anomaly.location}</td>
                                        <td style={{ padding: '12px' }}>
                                            <span style={{
                                                padding: '4px 12px',
                                                borderRadius: '12px',
                                                backgroundColor: anomaly.risk_level === 'critical' ? '#ffebee' : 
                                                               anomaly.risk_level === 'high' ? '#fff3e0' : '#e8f5e9',
                                                color: anomaly.risk_level === 'critical' ? '#c62828' : 
                                                       anomaly.risk_level === 'high' ? '#e65100' : '#2e7d32'
                                            }}>
                                                {anomaly.risk_level}
                                            </span>
                                        </td>
                                        <td style={{ padding: '12px' }}>
                                            <span style={{
                                                padding: '4px 12px',
                                                borderRadius: '12px',
                                                backgroundColor: getStatusColor(anomaly.status),
                                                color: getStatusTextColor(anomaly.status)
                                            }}>
                                                {getStatusLabel(anomaly.status)}
                                            </span>
                                        </td>
                                        <td style={{ padding: '12px' }}>{anomaly.reported_by__username || 'نامشخص'}</td>
                                        <td style={{ padding: '12px', textAlign: 'center' }}>
                                            <div style={{ display: 'flex', gap: '5px', justifyContent: 'center', flexWrap: 'wrap' }}>
                                                
                                                {/* تأیید - فقط سرپرست */}
                                                {anomaly.status === 'new' && canApprove && (
                                                    <button
                                                        onClick={() => handleAction(anomaly.id, 'approve')}
                                                        style={{
                                                            padding: '5px 10px',
                                                            backgroundColor: '#1976d2',
                                                            color: 'white',
                                                            border: 'none',
                                                            borderRadius: '4px',
                                                            cursor: 'pointer',
                                                            fontSize: '12px'
                                                        }}
                                                    >
                                                        ✅ تأیید
                                                    </button>
                                                )}

                                                {/* ارسال به کارشناس - فقط سرپرست */}
                                                {anomaly.status === 'approved' && canAssign && (
                                                    <div style={{ display: 'flex', gap: '5px' }}>
                                                        <select
                                                            onChange={(e) => setSelectedExpert({...selectedExpert, [anomaly.id]: e.target.value})}
                                                            style={{
                                                                padding: '5px',
                                                                borderRadius: '4px',
                                                                border: '1px solid #ddd',
                                                                fontSize: '12px'
                                                            }}
                                                        >
                                                            <option value="">انتخاب کارشناس</option>
                                                            {experts.map(expert => (
                                                                <option key={expert.id} value={expert.id}>
                                                                    {expert.username} ({expert.role})
                                                                </option>
                                                            ))}
                                                        </select>
                                                        <button
                                                            onClick={() => handleAction(anomaly.id, 'assign', { expert_id: selectedExpert[anomaly.id] })}
                                                            style={{
                                                                padding: '5px 10px',
                                                                backgroundColor: '#ff9800',
                                                                color: 'white',
                                                                border: 'none',
                                                                borderRadius: '4px',
                                                                cursor: 'pointer',
                                                                fontSize: '12px'
                                                            }}
                                                            disabled={!selectedExpert[anomaly.id]}
                                                        >
                                                            📌 ارسال
                                                        </button>
                                                    </div>
                                                )}

                                                {/* رفع - فقط کارشناس */}
                                                {anomaly.status === 'assigned' && canResolve && (
                                                    <button
                                                        onClick={() => handleAction(anomaly.id, 'resolve')}
                                                        style={{
                                                            padding: '5px 10px',
                                                            backgroundColor: '#4caf50',
                                                            color: 'white',
                                                            border: 'none',
                                                            borderRadius: '4px',
                                                            cursor: 'pointer',
                                                            fontSize: '12px'
                                                        }}
                                                    >
                                                        🔧 رفع
                                                    </button>
                                                )}

                                                {/* بستن - فقط سرپرست */}
                                                {anomaly.status === 'resolved' && canClose && (
                                                    <button
                                                        onClick={() => handleAction(anomaly.id, 'close')}
                                                        style={{
                                                            padding: '5px 10px',
                                                            backgroundColor: '#9c27b0',
                                                            color: 'white',
                                                            border: 'none',
                                                            borderRadius: '4px',
                                                            cursor: 'pointer',
                                                            fontSize: '12px'
                                                        }}
                                                    >
                                                        🔒 بستن
                                                    </button>
                                                )}

                                                {anomaly.status === 'closed' && (
                                                    <span style={{ color: '#2e7d32', fontWeight: 'bold' }}>
                                                        ✅ بسته شد
                                                    </span>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}

export default Anomalies;
